return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_DE','project-id-version'=>'RRZE Settings','pot-creation-date'=>'2026-09-15T13:20:35+00:00','po-revision-date'=>'2026-02-26 12:29+0100','x-generator'=>'Poedit 3.8','messages'=>['RRZE Settings'=>'RRZE-Einstellungen','https://github.com/RRZE-Webteam/rrze-settings'=>'https://github.com/RRZE-Webteam/rrze-settings','General settings and enhancements for a WordPress multisite installation.'=>'Allgemeine Einstellungen und Verbesserungen für eine WordPress Multisite-Installation.','RRZE Webteam'=>'RRZE-Webteam','https://www.wp.rrze.fau.de'=>'https://www.wp.rrze.fau.de','This feature has been disabled.'=>'Diese Funktion wurde deaktiviert.','Disabled'=>'Deaktiviert','Advanced'=>'Erweitert','Frontend Style'=>'Frontend Style','Backend Style'=>'Backend Style','BlockEditor iFrame Body Class'=>'Body-Klasse im Block-Editor-iFrame','Theme Exceptions'=>'Ausnahmen für Themes','Auto-generate Theme Classes'=>'Theme-Klassen automatisch generieren','Sentry Mode'=>'Sentry-Modus','Monitor Deleted Themes and Plugins'=>'Gelöschte Themes und Plugins überwachen','This page enables network administrators to centrally manage custom CSS styles for both the frontend and backend of every website in a multisite network, offering fields to input and organize CSS code and ensure advanced customization and consistent branding across the entire network.'=>'Diese Seite ermöglicht Netzwerkadministratoren, benutzerdefinierte CSS-Stile sowohl für das Frontend als auch für das Backend jeder Website in einem Multisite-Netzwerk zentral zu verwalten, bietet Felder zum Eingeben und Organisieren von CSS-Code und gewährleistet so erweiterte Anpassungen sowie ein konsistentes Branding im gesamten Netzwerk.','Enter the CSS code which will be added to the frontend of all websites.'=>'Geben Sie den CSS-Code ein, der dem Frontend aller Websites hinzugefügt wird.','Enter the CSS code which will be added to the backend of all websites.'=>'Geben Sie den CSS-Code ein, der dem Backend aller Websites hinzugefügt wird.','Enter a comma-separated list of CSS classes which will be injected into the body tag within the iFrame of the Block Editor.'=>'Geben Sie eine durch Kommas getrennte Liste von CSS-Klassen ein. Diese werden dem <body>-Element im iFrame des Block-Editors hinzugefügt.','Enter a comma-separated list of theme slugs (e.g., twentytwentyone, astra) where the Block Editor Body Class Injection should not be active.'=>'Geben Sie eine durch Kommas getrennte Liste von Theme-Slugs (z. B. twentytwentyone, astra) ein, bei denen die Body-Klassen-Injektion im Block-Editor nicht aktiv sein soll.','Automatically generate theme classes and inject them into the iFrame body tag.'=>'Theme-Klassen werden automatisch generiert und dem Body-Tag des Block-Editor-iFrames hinzugefügt.','Write a sentry marker file in the WordPress base directory whenever WordPress completes a core, plugin, theme, or translation install/update.'=>'Schreibt eine Sentry-Markierungsdatei in das WordPress-Basisverzeichnis, wenn WordPress eine Core-, Plugin-, Theme- oder Übersetzungsinstallation oder -aktualisierung abgeschlossen hat.','When Sentry Mode is active, also update the sentry marker file after successful plugin or theme deletions.'=>'Aktualisiert bei aktivem Sentry-Modus die Sentry-Markierungsdatei auch nach erfolgreichem Löschen von Plugins oder Themes.','Crawlers'=>'Crawler','Enter a name or Id for the crawler.'=>'Geben Sie einen Namen oder eine Id für den Crawler ein.','A crawler with this Id already exists.'=>'Ein Crawler mit dieser Id existiert bereits.','Enter a valid contact email address.'=>'Geben Sie eine gültige Kontakt-E-Mail-Adresse ein.','Enter a valid contact website URL.'=>'Geben Sie eine gültige URL für die Kontakt-Webseite ein.','Invalid IP addresses or ranges: %s'=>'Ungültige IP-Adressen oder IP-Bereiche: %s','Enter crawler data before saving.'=>'Geben Sie vor dem Speichern Crawler-Daten ein.','Add crawler'=>'Crawler hinzufügen','Network administrators can maintain known crawlers and their identifying data across the multisite network.'=>'Netzwerkadministratoren können bekannte Crawler und deren Erkennungsdaten im gesamten Multisite-Netzwerk verwalten.','Name'=>'Name','UserAgent'=>'UserAgent','IP addresses'=>'IP-Adressen','Contact'=>'Kontakt','Comment'=>'Kommentar','No crawlers found.'=>'Keine Crawler gefunden.','Edit'=>'Bearbeiten','Show more details'=>'Weitere Details anzeigen','Crawler not found'=>'Crawler nicht gefunden','Back to crawler list'=>'Zurück zur Crawler-Liste','Edit crawler'=>'Crawler bearbeiten','Id'=>'Id','Fixed user agent string or identifying part. Version numbers may differ.'=>'Fester User-Agent-String oder erkennender Bestandteil. Versionsnummern können abweichen.','IP addresses support IPv4, IPv6, CIDR notation, wildcards, and partial prefixes such as 131.188. or 2001:db8:. Enter one IP address or range per line.'=>'IP-Adressen unterstützen IPv4, IPv6, CIDR-Notation, Wildcards und Teilpräfixe wie 131.188. oder 2001:db8:. Geben Sie pro Zeile eine IP-Adresse oder einen IP-Bereich ein.','Contact email'=>'Kontakt-E-Mail','Contact website'=>'Kontakt-Webseite','Update crawler'=>'Crawler aktualisieren','Cancel'=>'Abbrechen','Internal unique crawler Id. Use lowercase letters, numbers, underscores, and hyphens.'=>'Interne eindeutige Crawler-Id. Verwenden Sie Kleinbuchstaben, Zahlen, Unterstriche und Bindestriche.','You are not allowed to delete this crawler.'=>'Sie dürfen diesen Crawler nicht löschen.','Crawler deleted.'=>'Crawler gelöscht.','Crawler saved.'=>'Crawler gespeichert.','Do you really want to delete this crawler?'=>'Möchten Sie diesen Crawler wirklich löschen?','Delete'=>'Löschen','Previous page'=>'Vorherige Seite','Next page'=>'Nächste Seite','%s item'=>'%s Eintrag' . "\0" . '%s Einträge','None'=>'Keine','%s more IP address'=>'%s weitere IP-Adresse' . "\0" . '%s weitere IP-Adressen','Content Security Police'=>'Content-Security-Police','CSP'=>'CSP','Enable CSP'=>'CSP aktivieren','Directives'=>'Direktiven','default-src'=>'default-src','script-src'=>'script-src','style-src'=>'style-src','img-src'=>'img-src','font-src'=>'font-src','connect-src'=>'connect-src','frame-src'=>'frame-src','The Content-Security-Policy HTTP response header helps to reduce XSS risks on modern browsers by declaring, which dynamic resources are allowed to load.'=>'Der Content-Security-Policy HTTP Response Header hilft, XSS-Risiken auf modernen Browsern zu reduzieren, indem er angibt, welche dynamischen Ressourcen geladen werden dürfen.','The Content-Security-Policy header value is made up of one or more directives (defined below). All of these directives ending in -src support similar values known as source lists.  Multiple source list values can be separated with a new line, except for \'none\', which should be the only value.'=>'Der Header-Wert der Content-Security-Policy setzt sich aus einer oder mehreren Direktiven zusammen (siehe unten). Alle diese Direktiven, die mit -src enden, unterstützen ähnliche Werte, die als Quelllisten bekannt sind.  Mehrere Quelllistenwerte können durch eine neue Zeile getrennt werden, mit Ausnahme von \'none\', das der einzige Wert sein sollte.','Enable Content Security Police'=>'Content-Security-Policy aktivieren','The default-src is the default policy for loading content such as JavaScript, Images, CSS, Fonts, AJAX requests, Frames, HTML5 Media.'=>'Das default-src ist die Standard-Policy für das Laden von Inhalten wie JavaScript, Bilder, CSS, Schriften, AJAX-Anfragen, Frames, HTML5-Medien.','Defines valid sources of JavaScript.'=>'Definiert gültige Quellen von JavaScript.','Defines valid sources of stylesheets.'=>'Definiert gültige Quellen von Stylesheets.','Defines valid sources of images.'=>'Definiert gültige Bildquellen.','Defines valid sources of fonts.'=>'Definiert gültige Schriftquellen.','Applies to XMLHttpRequest (AJAX), WebSocket or EventSource. If not allowed the browser emulates a 400 HTTP status code.'=>'Gilt für XMLHttpRequest (AJAX), WebSocket oder EventSource. Wenn nicht erlaubt, emuliert der Browser einen 400 HTTP-Statuscode.','Defines valid sources for embedding the resource using <frame> or <iframe>.'=>'Legt gültige Quellen fest, über die die Ressource mittels <frame> oder <iframe> eingebettet werden darf.','Yes, I understand the consequences and still want to create more administrators.'=>'Ja, ich verstehe die Konsequenzen und möchte dennoch weitere Administratoren erstellen.','RRZE Maintenance and fault messages'=>'RRZE Wartungs- und Fehlermeldungen','Webmaster News'=>'Webmaster Nachrichten','RSS-Error: %s'=>'RSS-Fehler: %s','Untitled'=>'Ohne Titel','General'=>'Allgemein','Translation Fallback'=>'Ersatzübersetzungen','Custom Error Page'=>'Benutzerdefinierte Fehlerseite','White Label'=>'White Label','Default Theme'=>'Standard-Theme','Manage translations, error messages and the WordPress administration interface across the network. The default theme applies only to newly created websites. Changes take effect after saving.'=>'Verwalten Sie Übersetzungen, Fehlermeldungen und die WordPress-Verwaltungsoberfläche im gesamten Netzwerk. Das Standard-Theme gilt nur für neu angelegte Websites. Änderungen werden nach dem Speichern wirksam.','Use available translations when a language file is missing'=>'Vorhandene Übersetzungen verwenden, wenn eine Sprachdatei fehlt','Uses another available language variant when a translation file is missing. Website content remains unchanged.'=>'Verwendet eine andere verfügbare Sprachvariante, wenn eine Übersetzungsdatei fehlt. Website-Inhalte bleiben unverändert.','If a translation file is missing or unreadable, look for an available variant of the same language first, then an English translation. For example, German can replace German (formal). This also applies to translations in the block editor.'=>'Fehlt eine Übersetzungsdatei oder ist sie nicht lesbar, wird zuerst nach einer verfügbaren Variante derselben Sprache und anschließend nach einer englischen Übersetzung gesucht. Beispielsweise kann Deutsch die Variante Deutsch (Sie) ersetzen. Dies gilt auch für Übersetzungen im Block-Editor.','Useful when plugins or themes do not provide every language variant. Does not translate website content, download language packs or fill individual gaps in an existing translation file. Disabled: WordPress handles translations without this additional fallback.'=>'Sinnvoll, wenn Plugins oder Themes nicht jede Sprachvariante mitliefern. Übersetzt keine Website-Inhalte, lädt keine Sprachpakete herunter und ergänzt keine einzelnen Lücken in einer vorhandenen Übersetzungsdatei. Deaktiviert: WordPress verarbeitet Übersetzungen ohne diesen zusätzlichen Fallback.','Use the RRZE error page for WordPress error messages'=>'RRZE-Fehlerseite für WordPress-Fehlermeldungen verwenden','Shows WordPress error messages in the RRZE layout. The website administration email address is displayed publicly as a contact; check that it is suitable before enabling this option.'=>'Zeigt WordPress-Fehlermeldungen im RRZE-Layout. Die Administrations-E-Mail-Adresse der Website wird öffentlich als Kontakt angezeigt; prüfen Sie vor dem Aktivieren, ob sie dafür geeignet ist.','For example, denied access is shown with the website name and a contact address. The layout links to /impressum, /datenschutz and /barrierefreiheit; check that these pages are available.'=>'Beispielsweise wird ein verweigerter Zugriff mit Website-Namen und Kontaktadresse angezeigt. Das Layout verlinkt auf /impressum, /datenschutz und /barrierefreiheit; prüfen Sie, ob diese Seiten erreichbar sind.','Applies to regular browser requests handled by wp_die(). Does not replace theme 404 pages, server error pages or AJAX, JSON and XML responses. If the admin page header has already been output, only the message is shown. Disabled: the WordPress error display is used.'=>'Gilt für normale Browseraufrufe, die über wp_die() behandelt werden. Ersetzt weder 404-Seiten des Themes noch Server-Fehlerseiten oder AJAX-, JSON- und XML-Antworten. Wurde der Kopf der Adminseite bereits ausgegeben, erscheint nur die Meldung. Deaktiviert: Die WordPress-Fehlerdarstellung wird verwendet.','Customize WordPress branding, dashboard and email sender'=>'WordPress-Branding, Dashboard und E-Mail-Absender anpassen','Customizes the admin bar, footer and dashboard together. Also replaces default WordPress email sender details with the website title and administration email address.'=>'Passt Adminleiste, Footer und Dashboard gemeinsam an. Ersetzt außerdem die Standard-Absenderangaben von WordPress-E-Mails durch Website-Titel und Administrations-E-Mail-Adresse.','Links the admin bar logo to the main website (site ID 1), removes WordPress information and support links, and shows the main website name and tagline in the admin footer. Sorts My Sites alphabetically.'=>'Verlinkt das Symbol in der Adminleiste mit der Hauptwebsite (Website-ID 1), entfernt WordPress-Informations- und Supportlinks und zeigt Name und Untertitel der Hauptwebsite im Admin-Footer. Sortiert „Meine Websites“ alphabetisch.','Replaces the WordPress news widget with RRZE maintenance messages and, on website dashboards, Webmaster News. Adds counts for additional content types to At a Glance.'=>'Ersetzt das WordPress-Nachrichten-Widget durch RRZE-Wartungsmeldungen und auf Website-Dashboards zusätzlich durch Webmaster-Nachrichten. Ergänzt „Auf einen Blick“ um Zähler für weitere Inhaltstypen.','For outgoing emails, replaces sender addresses beginning with wordpress@ with the current website administration email address, if valid, and the sender name WordPress with the website title. Other sender values are preserved. Disabled: these customizations are not applied.'=>'Ersetzt bei ausgehenden E-Mails Absenderadressen, die mit wordpress@ beginnen, durch die gültige Administrations-E-Mail-Adresse der aktuellen Website und den Absendernamen WordPress durch den Website-Titel. Andere Absenderwerte bleiben erhalten. Deaktiviert: Diese Anpassungen werden nicht angewendet.','Use WordPress default'=>'WordPress-Standard verwenden','Activates the selected theme only for newly created websites. Existing websites keep their current theme.'=>'Aktiviert das ausgewählte Theme nur für neu angelegte Websites. Bestehende Websites behalten ihr aktuelles Theme.','Select Use WordPress default to keep the theme chosen by WordPress during website creation. If the selected theme has been removed, this setting is skipped. Selecting a theme here does not enable it for selection across the network.'=>'Wählen Sie „WordPress-Standard verwenden“, um das von WordPress beim Anlegen der Website gewählte Theme beizubehalten. Wurde das ausgewählte Theme entfernt, wird diese Einstellung übersprungen. Die Auswahl hier gibt das Theme nicht netzwerkweit für die Theme-Auswahl frei.','For example, after changing the default from theme A to theme B, only new websites start with theme B. Existing websites using theme A are not switched.'=>'Wenn Sie beispielsweise den Standard von Theme A auf Theme B ändern, starten nur neue Websites mit Theme B. Bestehende Websites mit Theme A werden nicht umgestellt.','Details and examples'=>'Details und Beispiele','XML-RPC services are disabled on this site.'=>'XML-RPC-Dienste sind auf dieser Site deaktiviert.','Governance'=>'Governance','Websupport'=>'Websupport','Websupport Users'=>'Websupport-Benutzer','Websupport Role Name'=>'Websupport-Rollenname','Network administrators can define governance-related access rules for the multisite network on this page.'=>'Netzwerkadministratoren können auf dieser Seite governancebezogene Zugriffsregeln für das Multisite-Netzwerk definieren.','Enable network-wide websupport access'=>'Netzwerkweiten Websupport-Zugriff aktivieren','List of network users who receive websupport access. Enter one user ID, login, or email address per line.'=>'Liste der Netzwerkbenutzer, die Websupport-Zugriff erhalten. Geben Sie pro Zeile eine Benutzer-ID, einen Login-Namen oder eine E-Mail-Adresse ein.','Visible name for websupport users in user filters and user lists. The internal role identifier remains websupport.'=>'Sichtbarer Name für Websupport-Benutzer in Benutzerfiltern und Benutzerlisten. Die interne Rollenkennung bleibt websupport.','Heartbeat'=>'Heartbeat','Disable Heartbeat On Frontend'=>'Heartbeat im Frontend deaktivieren','Disable Heartbeat on the frontend for non-logged-in users (e.g., visitors).'=>'Deaktiviere Heartbeat im Frontend für nicht eingeloggte Nutzer (z. B. Besucher).','Disable Heartbeat In Admin Area'=>'Heartbeat im Admin-Bereich deaktivieren','Disable Heartbeat in the admin area (except on post editor screens).'=>'Deaktiviere Heartbeat im Admin-Bereich (außer auf Posts-Editor-Screens).','Force JS interval To Slow'=>'Erzwinge langsames JS-Intervall','Set the JavaScript interval to “slow” (about 60s) in the admin area as a fallback if other settings do not apply.'=>'Setze das JavaScript-Intervall im Admin-Bereich auf „slow“ (ca. 60 s) als Fallback, falls andere Einstellungen nicht greifen.','Editor interval'=>'Editor-Intervall','seconds'=>'Sekunden','Interval for post editors (seconds).'=>'Intervall für Posts-Editoren (Sekunden).','Admin Interval'=>'Admin-Intervall','Interval for other admin pages (seconds).'=>'Intervall für andere Admin-Seiten (Sekunden).','Role Overrides'=>'Rollen-Überschreibungen','Set custom Heartbeat intervals per role. Provide a JSON object where each role key contains two values: editor for post editor screens and default for other admin pages. Intervals are in seconds. Example: {"administrator":{"editor":15,"default":60},"editor":{"editor":30,"default":90},"author":{"editor":45,"default":120}}.'=>'Benutzerdefinierte Heartbeat-Intervalle pro Rolle festlegen. Es ist ein JSON-Objekt anzugeben, bei dem jeder Rollenschlüssel zwei Werte enthält: „editor“ für Beitragseditor-Seiten und „default“ für andere Admin-Seiten. Die Intervalle werden in Sekunden angegeben. Beispiel: {"administrator":{"editor":15,"default":60},"editor":{"editor":30,"default":90},"author":{"editor":45,"default":120}}.','Allowed Admin Page Hooks'=>'Erlaubte Admin-Seiten-Hooks','List of admin page hooks where Heartbeat is always allowed (one per line). Post editors (post.php, post-new.php) and the Site Editor are always allowed.'=>'Liste der Admin-Seiten-Hooks, auf denen Heartbeat immer erlaubt ist (ein Eintrag pro Zeile). Beitrags-Editoren (post.php, post-new.php) und der Site-Editor sind immer erlaubt.','This page enables network administrators to manage heartbeat-related settings across the multisite network.'=>'Auf dieser Seite können Netzwerk-Administratoren die Heartbeat-bezogenen Einstellungen im gesamten Multisite-Netzwerk verwalten.','Admin Email'=>'Admin E-Mail','Mail'=>'Mail','Envelope Sender'=>'Envelope-Sender','Allowed Domains'=>'Zulässige Domains','Admin Email Exceptions'=>'Admin-E-Mail-Ausnahmen','Centralized mail management for the multisite network enables defining the default envelope sender address, specifying permitted sender domains, and setting exceptions for editing admin email addresses—guaranteeing consistent, secure email delivery across all websites.'=>'Die zentralisierte E-Mail-Verwaltung für das Multisite‑Netzwerk ermöglicht die Festlegung der standardmäßigen Envelope‑Absenderadresse, die Spezifizierung erlaubter Absenderdomains und die Definition von Ausnahmen für die Bearbeitung von Administrator‑E-Mail‑Adressen—und gewährleistet so eine konsistente, sichere E-Mail‑Zustellung über alle Websites hinweg.','Set the default envelope sender.'=>'Envelope-Sender festlegen.','List of allowed domains for email addresses used as envelope sender.'=>'Liste der zulässigen Domains für E-Mail-Adressen, die als Envelope-Sender verwendet werden können.','List of website IDs that can edit the admin_email field. Enter one website ID per line.'=>'Liste der Website-IDs, die das Feld admin_email bearbeiten können. Geben Sie pro Zeile eine Website-ID ein.','CMS'=>'CMS','Size'=>'Größe','Replace Media'=>'Ersetzen von Medien','Replace this file.'=>'Diese Datei ersetzen.','action of rrze-media-replaceReplace File'=>'Datei ersetzen','Replace File'=>'Datei ersetzen','Current file does not exist.'=>'Die aktuelle Datei existiert nicht.','Please select a file to upload.'=>'Bitte wählen Sie eine Datei zum Hochladen aus.','It was not possible to upload the file.'=>'Es war nicht möglich, die Datei hochzuladen.','This media type is not permitted for security reasons.'=>'Dieser Medientyp ist aus Sicherheitsgründen nicht zulässig.','The media type does not match existing file.'=>'Der Medientyp stimmt nicht mit der vorhandenen Datei überein.','The file %s can not be deleted by the web server, most likely because the permissions on the file are wrong.'=>'Die Datei %s kann vom Webserver nicht gelöscht werden, höchstwahrscheinlich weil die Berechtigungen für die Datei falsch sind.','This is a placeholder for the media replace page.'=>'Dies ist ein Platzhalter für die Medien-Ersetzungsseite.','You do not have permission to upload files.'=>'Du hast keine Berechtigung zum Hochladen von Dateien.','Nothing selected.'=>'Es wurde nichts ausgewählt.','Error: %s'=>'Fehler: %s','You are about to replace the media file "%s".'=>'Sie sind dabei, die Mediendatei „%s“ zu ersetzen.','Select a file'=>'Eine Datei auswählen','The file must be of the same media type (%1$s) as the one being replaced. The name of the file (%2$s) will stay the same.'=>'Die Datei muss vom gleichen Medientyp (%1$s) sein wie die zu ersetzende Datei. Der Name der Datei (%2$s) bleibt gleich.','Upload'=>'Hochladen','Media'=>'Medien','Sanitize filename'=>'Dateiname bereinigen','Filter Non-Images'=>'Nicht-Bilder filtern','Automatic Image Resizing'=>'Automatische Bildgrößenanpassung','Sharpen JPG Images'=>'JPG-Bilder schärfen','SVG Support'=>'SVG-Unterstützung','File Replace'=>'Datei ersetzen','File Size Column'=>'Dateigröße Spalte','Custom Mime Types'=>'Benutzerdefinierte Mime-Typen','Taxonomien'=>'Taxonomien','Register Attachment Document'=>'Mediendokument registrieren','Register Attachment Category'=>'Medienkategorie registrieren','Register Attachment Tag'=>'Medienschlagwort registrieren','Network administrators can centrally manage media settings across the multisite network. Options include sanitizing filenames, filtering non‑image MIME types, enabling automatic image resizing and sharpening, supporting SVG uploads, replacing files, displaying file sizes, and defining custom MIME types—ensuring consistent, secure media handling on every website.'=>'Netzwerkadministratoren können Medieneinstellungen im gesamten Multisite‑Netzwerk zentral verwalten. Zu den Optionen gehören die Bereinigung von Dateinamen, das Filtern nicht bildbezogener MIME‑Typen, das Aktivieren der automatischen Bildgrößenanpassung und -schärfung, die Unterstützung von SVG‑Uploads, das Ersetzen von Dateien, die Anzeige von Dateigrößen sowie das Definieren benutzerdefinierter MIME‑Typen — und gewährleisten so eine konsistente, sichere Medienverwaltung auf jeder Website.','Configure taxonomies for media attachments across the multisite network.'=>'Konfiguriert Taxonomien für Medienanhänge im gesamten Multisite-Netzwerk.','Register attachment document taxonomy'=>'Mediendokument-Taxonomie registrieren','Register attachment category taxonomy'=>'Medienkategorie-Taxonomie registrieren','Register attachment tag taxonomy'=>'Medienschlagwort-Taxonomie registrieren','Sanitize the filenames to avoid links with UTF-8 characters'=>'Bereinigt die Dateinamen, um Links mit UTF-8-Zeichen zu vermeiden','Filters the image sizes generated for non-image mime types'=>'Filtert die Bildgrößen, die für Mime-Typen ohne Bild erzeugt werden','Size in pixels'=>'Größe in Pixel','Enables sharpening of JPG images'=>'Ermöglicht die Schärfung von JPG-Bildern','Enables support for SVG files'=>'Ermöglicht die Unterstützung von SVG-Dateien','Enables the file size column'=>'Aktiviert die Spalte Dateigröße','Enter custom Mime Types. Make sure to add the respective extensions in the Upload File Types settings.'=>'Geben Sie benutzerdefinierte Mime-Typen ein. Stellen Sie sicher, dass Sie die entsprechenden Erweiterungen in den Einstellungen für Upload-Dateitypen hinzufügen.','To leave a comment, type two forward slashes (//) followed by the text of your comment.'=>'Um einen Kommentar zu hinterlassen, geben Sie zwei Schrägstriche (//) gefolgt vom Text Ihres Kommentars ein.','One custom Mime Type per line.'=>'Ein benutzerdefinierter Mime-Typ pro Zeile.','Allows to replace files of the same mime type'=>'Ermöglicht das Ersetzen von Dateien des gleichen Mime-Typs','Menus'=>'Menüs','Collapse'=>'Ausklappen','Expand'=>'Aufklappen','Expand Collapse'=>'Ein‑/Ausklappen','Custom Column'=>'Benutzerdefinierte Spalte','Enhanced Search'=>'Erweiterte Suche','Network administrators can manage menu-related settings across the multisite network from a centralized location. Options include enabling expand/collapse functionality for menu items, adding a custom column to the posts list, and improving menu search capabilities—enhancing efficiency and usability across all websites.'=>'Netzwerkadministratoren können menübezogene Einstellungen im gesamten Multisite‑Netzwerk von einem zentralen Ort aus verwalten. Zu den Optionen gehören das Aktivieren der Ein‑/Ausklappfunktion für Menüpunkte, das Hinzufügen einer benutzerdefinierten Spalte in der Beitragsliste und die Verbesserung der Menüsuchfunktionen — zur Steigerung von Effizienz und Benutzerfreundlichkeit auf allen Websites.','Expands and collapses menu items'=>'Ein‑/Ausklappen von Menüelementen','Creates a custom column (Menus) in the posts list'=>'Erstellt eine benutzerdefinierte Spalte (Menüs) in der Posts-Liste','Enhanced menu search'=>'Erweiterte Menüsuche','Plugins'=>'Plugins','Save Changes'=>'Änderungen speichern','DIP'=>'DIP','DIP API Key'=>'DIP API-Key','DIP Edu API key'=>'DIP Edu-API-Key','FAUdir'=>'FAUdir','FAUdir API Key'=>'FAUdir-API-Key','RRZE Jobs'=>'RRZE-Jobs','B-ITE API Key'=>'B-ITE-API-Key','RRZE Search Settings'=>'RRZE-Sucheinstellungen','Search Engine Keys'=>'API-Schlüssel für Suchmaschinen','Daily Limit'=>'Tageslimit','Weekly Limit'=>'Wochenlimit','Monthly Limit'=>'Monatslimit','Yearly Limit'=>'Jahreslimit','RRZE WebT'=>'RRZE-WebT','API Endpoint URL'=>'API-Endpunkt-URL','Application Name'=>'Anwendungsname','Password'=>'Passwort','Exceptions'=>'Ausnahmen','RRZE Newsletter'=>'RRZE-Newsletter','Global Settings'=>'Globale Einstellungen','Allowed domains for Envelope Sender'=>'Zulässige Domains für Envelope-Sender','Send Limit'=>'Sende-Limit','Max. Retries'=>'Max. Wiederholungen','Disable subscription'=>'Abonnement deaktivieren','Allowed domains for recipients'=>'Zulässige Domains für Empfänger','RRZE Formular'=>'RRZE Formular','CMS Workflow'=>'CMS-Workflow','Not Allowed Post Types'=>'Nicht zulässige Post-Types','WS Form'=>'WS-Form','License Key'=>'Lizenz-Key','PDF Add-On License Key'=>'PDF Add-On Lizenz-Key','Not Allowed Field Types'=>'Nicht zulässige Feldtypen','RRZE Directions'=>'RRZE Directions','OpenRouteService-API-Key'=>'OpenRouteService-API-Key','Contact Form 7'=>'CF7','Dequeue scripts'=>'Skripte aus Queue entfernen','SEO Framework'=>'SEO-Framework','Force activation'=>'Aktivierung erzwingen','Siteimprove'=>'Siteimprove','Crawler IP addresses'=>'Crawler-IP-Adressen','Schlüsselcode'=>'Schlüsselcode','Network administrators can oversee and configure plugin settings across a multisite environment. The page automatically detects supported plugins and presents dedicated sections and fields for each one. Network administrators can enter API keys, adjust plugin‑specific options, and maintain efficient, consistent management of all websites in the network.'=>'Netzwerkadministratoren können Plugin‑Einstellungen in einer Multisite‑Umgebung zentral überwachen und konfigurieren. Die Seite erkennt automatisch unterstützte Plugins und stellt für jedes Plugin eigene Abschnitte und Felder bereit. Netzwerkadministratoren können API‑Keys eingeben, plugin‑spezifische Optionen anpassen und so eine effiziente, konsistente Verwaltung aller Websites im Netzwerk gewährleisten.','Enter one search engine per block (3 or 4 lines):'=>'Bitte pro Block genau eine Suchmaschine angeben (3–4 Zeilen):','Line 1: Name'=>'1. Zeile: Name','Line 2: CX'=>'2. Zeile: CX','Line 3: API'=>'3. Zeile: API','Optional line 4: Description'=>'(Optional) 4. Zeile: Beschreibung','Add multiple engines by adding additional 3/4-line blocks (no empty lines required).'=>'Mehrere Suchmaschinen können durch zusätzliche 3/4-Zeilen-Blöcke hinzugefügt werden – Leerzeilen sind nicht erforderlich.','Maximum number of RRZE Search requests per day. Use 0 for unlimited.'=>'Maximale Anzahl an RRZE-Search-Anfragen pro Tag. Verwenden Sie 0 für unbegrenzt.','Maximum number of RRZE Search requests per week. Use 0 for unlimited.'=>'Maximale Anzahl an RRZE-Search-Anfragen pro Woche. Verwenden Sie 0 für unbegrenzt.','Maximum number of RRZE Search requests per month. Use 0 for unlimited.'=>'Maximale Anzahl an RRZE-Search-Anfragen pro Monat. Verwenden Sie 0 für unbegrenzt.','Maximum number of RRZE Search requests per year. Use 0 for unlimited.'=>'Maximale Anzahl an RRZE-Search-Anfragen pro Jahr. Verwenden Sie 0 für unbegrenzt.','The WebT API Url used for RRZE Webt.'=>'Die WebT-API-URL, die von RRZE Webt verwendet wird.','The WebT application name used for RRZE Webt.'=>'Der WebT-Anwendungsname, der von RRZE Webt verwendet wird.','The WebT password used for RRZE Webt.'=>'Das WebT-Passwort, das von RRZE Webt verwendet wird.','List of IDS of websites that are exempt to all global settings. Enter one website ID per line.'=>'Liste der IDs von Websites, die alle globalen Einstellungen befreit sind. Geben Sie eine Website-ID pro Zeile ein.','Activate the global settings of the plugin'=>'Die globalen Einstellungen des Plugins aktivieren','List of allowed domains for envelope sender. Enter one domain per line.'=>'Liste der zulässigen Domänen für Envelope-Sender. Geben Sie eine Domäne pro Zeile ein.','Maximum number of emails that can be sent per minute.'=>'Maximale Anzahl von E-Mails, die pro Minute gesendet werden können.','Maximum number of retries until an email is sent successfully.'=>'Maximale Anzahl von Wiederholungsversuchen, bis eine E-Mail erfolgreich gesendet wurde.','Disables the subscription and mailing lists'=>'Deaktiviert die Abonnement und Mail-Listen','List of allowed domains for recipients. Enter one domain per line.'=>'Liste der zulässigen Domänen für Empfänger. Geben Sie eine Domäne pro Zeile ein.','List of allowed domains for RRZE Formular. Enter one domain without www per line.'=>'Liste der zulässigen Domänen für RRZE Formular. Geben Sie pro Zeile eine Domäne ohne www ein.','Schlüssel unter'=>'Schlüssel unter','https://openrouteservice.org'=>'https://openrouteservice.org','beantragen und hier einfügen.'=>'beantragen und hier einfügen.','List of not allowed post types. Enter one post type per line.'=>'Liste der nicht erlaubten Post-Types. Geben Sie einen Post-Type pro Zeile ein.','List of allowed IP addresses of the Siteimprove crawler in case there are access restrictions to the content of the website. Enter one IP address per line.'=>'Liste der zulässigen IP-Adressen des Siteimprove-Crawlers. Geben Sie eine IP-Adresse pro Zeile ein.','4 bis 10 alphanumerische Zeichen.'=>'4 bis 10 alphanumerische Zeichen.','Disables custom columns and metaboxes'=>'Deaktiviert benutzerdefinierte Spalten und Metaboxen','Dequeue Contact Form 7 scripts on the posts where it is not needed'=>'Dequeue Contact-Form-7-Skripte an den Posts, an denen es nicht benötigt wird','Forces the activation of the plugin if it exists and has not yet been activated'=>'Erzwingt die Aktivierung des Plugins, wenn es existiert und noch nicht aktiviert wurde','This license key will apply to all websites.'=>'Dieser Lizenz-Key gilt für alle Websites.','This add-on license key will apply to all websites.'=>'Dieser Add-On-Lizenz-Key gilt für alle Websites.','List of not allowed field types. Enter one field type per line.'=>'Liste der nicht zulässigen Feldtypen. Geben Sie einen Feldtyp pro Zeile ein.','The DIP API key used by some plugins.'=>'Der DIP‑API‑Key, der von einigen Plugins verwendet wird.','The DIP Edu API key used by some plugins.'=>'Der DIP Edu‑API‑Key, der von einigen Plugins verwendet wird.','The FAUdir API key to access the API service https://api.fau.de/.'=>'Der FAUdir‑API‑Key zum Zugriff auf den API‑Dienst https://api.fau.de/.','The B-ITE API key used for RRZE Jobs.'=>'Der für RRZE-Jobs verwendete B—ITE-API-Key.','Save all changes'=>'Alle Änderungen speichern','Saves the settings in all plugin sections on this page.'=>'Speichert die Einstellungen aller Plugin-Abschnitte auf dieser Seite.','Jump to plugin'=>'Zum Plugin springen','Back to overview'=>'Zur Übersicht','All page levels'=>'Alle Seitenebenen','Posts'=>'Posts','Last Modified'=>'Letzte Änderung','Pages List Dropdown'=>'Dropdown-Liste der Seiten','Register Page Category'=>'Seitenkategorie registrieren','Register Page Tag'=>'Seitenschlagwort registrieren','No-Search Posts'=>'No-Search-Posts','Network administrators can centrally manage post settings across the multisite network. Options include adding a custom “Last Modified” column to post lists and a dropdown filter for pages—enhancing content visibility and management across all websites.'=>'Netzwerkadministratoren können Beitragseinstellungen im gesamten Multisite‑Netzwerk zentral verwalten. Zu den Optionen gehören das Hinzufügen einer benutzerdefinierten Spalte „Zuletzt bearbeitet“ in den Beitragslisten und ein Dropdown‑Filter für Seiten — zur Verbesserung der Inhaltsübersicht und -verwaltung auf allen Websites.','Configure taxonomies and search behavior for posts and pages across the multisite network.'=>'Taxonomien und Suchverhalten für Beiträge und Seiten im gesamten Multisite-Netzwerk konfigurieren.','Exclude from search nosearch-tagged posts'=>'Posts mit dem Schlagwort nosearch von der Suche ausschließen','Register page category taxonomy'=>'Seitenkategorie-Taxonomie registrieren','Register page tag taxonomy'=>'Seitenschlagwort-Taxonomie registrieren','Enables last modified custom column'=>'Aktiviert die zuletzt geänderte benutzerdefinierte Spalte','Enables pages list dropdown'=>'Aktiviert die Dropdown-Liste der Seiten','REST API support is restricted.'=>'Die Unterstützung der REST-API ist eingeschränkt.','%s (including subroutes)'=>'%s (einschließlich Unterrouten)','Network allowlist entry. Permits public read access to this route and its subroutes. Registered public endpoints require their own approval.'=>'Eintrag aus der Netzwerkfreigabeliste. Erlaubt öffentlichen Lesezugriff auf diese Route und ihre Unterrouten. Registrierte öffentliche Endpunkte benötigen ihre eigene Freigabe.','REST API'=>'REST-API','REST API Settings'=>'REST-API-Einstellungen','Allowed ip addresses'=>'Zulässige IP-Adressen','Allowed namespaces and routes'=>'Erlaubte Namespaces und Routen','Registered public endpoints'=>'Registrierte öffentliche Endpunkte','Network administrators can centrally configure REST API access across the multisite network. The settings lets them disable the API for non‑authenticated users, whitelist specific IP addresses, and permit chosen namespaces—strengthening security and access control on every website.'=>'Netzwerkadministratoren können den REST‑API‑Zugriff im gesamten Multisite‑Netzwerk zentral konfigurieren. Die Einstellungen ermöglichen es, die API für nicht authentifizierte Benutzer zu deaktivieren, bestimmte IP‑Adressen auf die Whitelist zu setzen und ausgewählte Namespaces zu erlauben — und stärken so die Sicherheit und Zugriffskontrolle auf jeder Website.','Disables the REST API for visitors who are not logged in.'=>'Deaktiviert die REST-API für Besucher, die nicht angemeldet sind.','Enter the IP addresses that allow access to the REST API when disabled.'=>'Die IP-Adressen eingeben, die den Zugriff auf die REST-API ermöglichen, wenn sie deaktiviert ist. Eine IP-Adresse pro Zeile.','To leave a comment, type a hash symbol (#) followed by the text of your comment.'=>'Um einen Kommentar zu hinterlassen, geben Sie ein Hash-Symbol (#) gefolgt vom Text Ihres Kommentars ein.','One IP address or IP range per line.'=>'Eine IP-Adresse oder ein IP-Bereich pro Zeile.','Enter one REST API namespace or route per line, for example /wp/v2/pages. Each entry includes its subroutes and permits access when the general REST API restriction is enabled.'=>'Pro Zeile einen REST-API-Namespace oder eine Route eingeben, zum Beispiel /wp/v2/pages. Jeder Eintrag umfasst seine Unterrouten und erlaubt den Zugriff bei aktivierter allgemeiner REST-API-Sperre.','Private Site administrators can additionally select these entries for public GET and HEAD access on their own site. Registered public endpoints always require their separate checkbox approval.'=>'Betreiber privater Websites können diese Einträge zusätzlich für öffentliche GET- und HEAD-Anfragen auf ihrer Website auswählen. Registrierte öffentliche Endpunkte benötigen immer ihre eigene Checkbox-Freigabe.','No installed plugin has declared a public REST API endpoint.'=>'Bisher wurde kein öffentlicher REST-API-Endpunkt eines installierten Plugins erkannt.','Registered endpoints require explicit approval for anonymous access, even when the general REST API restriction is off or an IP address or namespace is allowed. Only the exact route and listed methods are approved. Visitors without existing access to a private site additionally need a local endpoint selection (GET and HEAD only). Endpoint permission checks still apply.'=>'Registrierte Endpunkte benötigen eine ausdrückliche Freigabe für anonyme Zugriffe, auch bei ausgeschalteter allgemeiner REST-API-Sperre oder erlaubter IP-Adresse beziehungsweise erlaubtem Namespace. Die Freigabe gilt nur für die genaue Route und die aufgeführten Methoden. Für Besucher ohne bestehende Zugangsberechtigung zur privaten Website muss der Betreiber den Endpunkt zusätzlich lokal auswählen (nur GET und HEAD). Die Berechtigungsprüfung des Endpunkts bleibt wirksam.','Settings saved.'=>'Einstellungen gespeichert.','Attachment Categories'=>'Medienkategorien','Attachment Category'=>'Medienkategorie','Search Categories'=>'Kategorien suchen','Alle Categories'=>'Alle Kategorien','Parent Category'=>'Übergeordnet','Parent Category:'=>'Übergeordnet:','Edit Category'=>'Kategorie bearbeiten','Update Category'=>'Kategorie aktualisieren','Add New Category'=>'Neue Kategorie hinzufügen','Categories'=>'Kategorien','— No category —'=>'— Keine Kategorie —','Category'=>'Kategorie','Choose a category for this file. If left empty, a default will be assigned.'=>'Bitte eine Kategorie für diese Datei wählen. Wird keine angegeben, erfolgt eine automatische Standardzuweisung.','Documents'=>'Dokumente','Document'=>'Dokument','Search Documents'=>'Dokumente suchen','All Documents'=>'Alle Dokumente','Parent Document'=>'Übergeordnet','Parent Document:'=>'Übergeordnet:','Attachment Tags'=>'Medienschlagwörter','Attachment Tag'=>'Medienschlagwort','Search Tags'=>'Schlagwörter suchen','Popular Tags'=>'Beliebte Schlagwörter','All Tags'=>'Alle Schlagwörter','Edit Tag'=>'Schlagwort bearbeiten','Update Tag'=>'Schlagwort aktualisieren','Add New Tag'=>'Neues Schlagwort erstellen','Separate tags with commas'=>'Trenne Schlagwörter durch Kommas','Add'=>'Hinzu','Choose from the most used tags'=>'Wähle aus den häufig genutzten Schlagwörter','Tags'=>'Schlagwörter','All Categories'=>'Alle Kategorien','Page Categories'=>'Seitenkategorien','Page Category'=>'Seitenkategorie','Page Tags'=>'Seitenschlagworte','Page Tag'=>'Seitenschlagwort','The term can not be deleted.'=>'Der Term kann nicht gelöscht werden.','You are not allowed to delete this website.'=>'Es ist Ihnen nicht gestattet, diese Website zu löschen.','post_name (slug)contact'=>'kontakt','post_titleContact'=>'Kontakt','Contact persons'=>'Kontaktpersonen','Email Address:'=>'E-Mail-Adresse:','Pages Author'=>'Seitenautor','Super Author'=>'Superautor','Users'=>'Benutzer','Contact Page'=>'Kontaktseite','Welcome Panel'=>'Willkommenspanel','Admin Role Threshold Warning'=>'Administrator-Grenzwert-Warnung','User Search'=>'Benutzersuche','Debug Log Access'=>'Debug-Zugriff','Manage additional author roles, user search, contact information and dashboard guidance across the network. You can also configure administrator warnings and access to debug information. Changes take effect after saving.'=>'Verwalten Sie zusätzliche Autorenrollen, Benutzersuche, Kontaktinformationen und Dashboard-Hinweise im gesamten Netzwerk. Außerdem können Sie Administrator-Warnungen und den Zugriff auf Debug-Informationen konfigurieren. Änderungen werden nach dem Speichern wirksam.','Hide the WordPress welcome panel'=>'WordPress-Willkommenspanel ausblenden','Removes the WordPress introduction panel from website dashboards. Other dashboard widgets remain available.'=>'Entfernt das WordPress-Willkommenspanel von den Website-Dashboards. Andere Dashboard-Widgets bleiben verfügbar.','Useful when users receive their introduction through your own training or documentation. This option does not change user roles or permissions.'=>'Sinnvoll, wenn Benutzer eine eigene Schulung oder Dokumentation zur Einführung erhalten. Diese Option ändert keine Benutzerrollen oder Berechtigungen.','Disabled: WordPress controls the welcome panel again. Whether an individual user sees it also depends on their permissions and personal display settings.'=>'Deaktiviert: WordPress steuert das Willkommenspanel wieder selbst. Ob eine Person es sieht, hängt auch von ihren Berechtigungen und persönlichen Anzeigeeinstellungen ab.','Ask for confirmation before assigning more administrators'=>'Vor der Zuweisung weiterer Administratoren eine Bestätigung verlangen','Warns when a website already has at least the configured number of administrators and an existing user is promoted. The warning can be confirmed; it is not a fixed limit.'=>'Warnt beim Hochstufen eines bestehenden Benutzers, wenn die Website bereits mindestens die eingestellte Anzahl an Administratoren hat. Die Warnung kann bestätigt werden; sie ist keine feste Obergrenze.','Administrator threshold per website'=>'Administrator-Schwellenwert pro Website','Minimum and default: 3. Used only while the warning is enabled.'=>'Mindestwert und Standard: 3. Wird nur bei aktivierter Warnung verwendet.','Example: with a threshold of 3 and three existing administrators, promoting another user requires typing the displayed confirmation phrase. Existing administrators keep their role.'=>'Beispiel: Bei Schwelle 3 und drei vorhandenen Administratoren muss beim Hochstufen eines weiteren Benutzers die angezeigte Bestätigungsphrase eingegeben werden. Bestehende Administratoren behalten ihre Rolle.','The check runs in the user management screens of individual websites, including bulk role changes. It counts users with the Administrator role on that website, not all network super administrators.'=>'Die Prüfung läuft in der Benutzerverwaltung einzelner Websites, auch bei Mehrfachänderungen von Rollen. Gezählt werden Benutzer mit der Rolle Administrator auf dieser Website, nicht alle Superadministratoren des Netzwerks.','The current count is checked before the change. A bulk change that crosses the threshold from below does not trigger the warning. Actions without an existing user ID, such as creating a new account, are not covered.'=>'Geprüft wird die Anzahl vor der Änderung. Eine Mehrfachänderung, die die Schwelle erst überschreitet, löst keine Warnung aus. Vorgänge ohne vorhandene Benutzer-ID, etwa das Anlegen eines neuen Kontos, sind nicht abgedeckt.','This is a JavaScript confirmation, not a server-enforced restriction. Network administration, API requests and command-line changes are not covered. Disabled: this additional confirmation is omitted.'=>'Dies ist eine Bestätigung per JavaScript, keine serverseitig erzwungene Beschränkung. Änderungen über Netzwerkverwaltung, API und Kommandozeile sind nicht abgedeckt. Deaktiviert: Diese zusätzliche Bestätigung entfällt.','Make the Pages Author role available'=>'Rolle Seitenautor bereitstellen','Allows users to create, publish and manage their own pages and upload media. Before disabling, assign affected users another role so they retain the access they need.'=>'Erlaubt das Erstellen, Veröffentlichen und Verwalten eigener Seiten sowie Medien-Uploads. Weisen Sie betroffenen Benutzern vor dem Deaktivieren eine andere Rolle zu, damit sie ihren benötigten Zugriff behalten.','Suitable for people who maintain their own pages but do not need to write posts. Includes editing and deleting their own published pages; does not grant management of other users, website settings or pages written by others.'=>'Geeignet für Personen, die eigene Seiten pflegen, aber keine Beiträge schreiben müssen. Umfasst auch das Bearbeiten und Löschen eigener veröffentlichter Seiten. Gewährt keine Verwaltung anderer Benutzer, Website-Einstellungen oder fremder Seiten.','Enabling makes the role available for assignment; it does not assign it to anyone automatically. Role definitions are added or removed when each website loads, rather than updating all websites at once.'=>'Aktivieren stellt die Rolle zur Zuweisung bereit; niemand erhält sie automatisch. Rollendefinitionen werden beim Laden der jeweiligen Website angelegt oder entfernt, nicht auf allen Websites gleichzeitig.','Disabling removes the role definition. Existing role assignments are not migrated, so affected users lose the permissions supplied by this role. Their content is not deleted.'=>'Deaktivieren entfernt die Rollendefinition. Bestehende Rollenzuweisungen werden nicht migriert; betroffene Benutzer verlieren die Berechtigungen aus dieser Rolle. Ihre Inhalte werden nicht gelöscht.','Make the Super Author role available'=>'Rolle Superautor bereitstellen','Allows users to create, publish and manage their own posts and pages and upload media. Before disabling, assign affected users another role so they retain the access they need.'=>'Erlaubt das Erstellen, Veröffentlichen und Verwalten eigener Beiträge und Seiten sowie Medien-Uploads. Weisen Sie betroffenen Benutzern vor dem Deaktivieren eine andere Rolle zu, damit sie ihren benötigten Zugriff behalten.','Combines work on own posts and pages, including editing and deleting published content. It does not grant editing of content written by others, user management or website administration. Super Author is not a network super administrator.'=>'Verbindet die Arbeit an eigenen Beiträgen und Seiten, einschließlich des Bearbeitens und Löschens veröffentlichter Inhalte. Gewährt keine Bearbeitung fremder Inhalte, Benutzerverwaltung oder Website-Administration. Superautor ist kein Netzwerk-Superadministrator.','Include first and last names in user searches'=>'Vor- und Nachnamen bei der Benutzersuche berücksichtigen','Adds matching profile information to searches in user lists. Useful when you know a person by name rather than by their login.'=>'Ergänzt die Suche in Benutzerlisten um passende Profildaten. Hilfreich, wenn Sie eine Person unter ihrem Namen statt unter ihrem Login kennen.','Searches first name, last name, login, display name, email address, website URL and the URL-friendly user name. For example, Anna Meyer can match first and last names stored in separate profile fields.'=>'Durchsucht Vorname, Nachname, Login, Anzeigename, E-Mail-Adresse, Website-URL und den für URLs verwendeten Benutzernamen. Beispielsweise kann Anna Meyer passende Vor- und Nachnamen in getrennten Profilfeldern finden.','Multiple words must all match for an additional result; partial matches are supported. Searches containing @ use the normal WordPress search. This option does not add a search to the public website.'=>'Für einen zusätzlichen Treffer müssen alle eingegebenen Wörter passen; Teiltreffer sind möglich. Suchen mit @ verwenden die normale WordPress-Suche. Diese Option ergänzt keine Suche auf der öffentlichen Website.','Disabled: user lists use the normal WordPress search without these additional matches.'=>'Deaktiviert: Benutzerlisten verwenden die normale WordPress-Suche ohne diese zusätzlichen Treffer.','Provide an automatic contact page'=>'Automatische Kontaktseite bereitstellen','Lists website administrators with their display names and email addresses on a public-facing contact page. Check that these details are suitable for publication. The main website is excluded.'=>'Listet Website-Administratoren mit Anzeigenamen und E-Mail-Adressen auf einer Kontaktseite im Frontend auf. Prüfen Sie, ob diese Daten veröffentlicht werden dürfen. Die Hauptwebsite ist ausgenommen.','The address follows the website language, for example /kontakt/ in German and /contact/ in English. It lists accounts with the Administrator role on that website; network super administrators are not automatically included.'=>'Die Adresse richtet sich nach der Website-Sprache, etwa /kontakt/ auf Deutsch und /contact/ auf Englisch. Aufgelistet werden Konten mit der Rolle Administrator auf dieser Website; Netzwerk-Superadministratoren werden nicht automatisch aufgenommen.','An existing page with the same slug prevents the virtual page, including drafts, private pages and nested pages. This does not publish or move that existing page.'=>'Eine vorhandene Seite mit demselben Slug verhindert die virtuelle Seite, auch bei Entwürfen, privaten oder untergeordneten Seiten. Die vorhandene Seite wird dadurch weder veröffentlicht noch verschoben.','The contact page is generated when requested and is not stored as an editable page. To provide your own content, create a normal page with the matching slug. Existing website access restrictions still apply.'=>'Die Kontaktseite wird beim Aufruf erzeugt und nicht als bearbeitbare Seite gespeichert. Erstellen Sie für eigene Inhalte eine normale Seite mit dem passenden Slug. Bestehende Zugriffsbeschränkungen der Website gelten weiterhin.','Disabled: the virtual page is no longer generated. Any normal contact page remains unchanged.'=>'Deaktiviert: Die virtuelle Seite wird nicht mehr erzeugt. Eine normale Kontaktseite bleibt unverändert.','Enter one exact user login per line, not a display name, email address or user ID. Listed accounts can view debug information in components that use this permission check. Super administrators are always allowed.'=>'Geben Sie pro Zeile einen exakten Login-Namen ein, keinen Anzeigenamen, keine E-Mail-Adresse und keine Benutzer-ID. Eingetragene Konten dürfen Debug-Informationen in Komponenten sehen, die diese Berechtigungsprüfung verwenden. Superadministratoren sind immer zugelassen.','For example, enter anna.meyer and max.mustermann on separate lines. Use the spelling and capitalization of the actual login. An empty list allows only super administrators through this check.'=>'Tragen Sie beispielsweise anna.meyer und max.mustermann in getrennten Zeilen ein. Verwenden Sie die Schreibweise und Groß-/Kleinschreibung des tatsächlichen Logins. Eine leere Liste lässt bei dieser Prüfung nur Superadministratoren zu.','This network-wide list is evaluated by Helper::userCanViewDebugLog(). It does not enable logging, create a log viewer or grant general website access. Other components may apply additional access checks.'=>'Diese netzwerkweite Liste wird durch Helper::userCanViewDebugLog() ausgewertet. Sie aktiviert keine Protokollierung, erstellt keinen Log-Viewer und gewährt keinen allgemeinen Website-Zugang. Andere Komponenten können zusätzliche Zugriffsprüfungen durchführen.','Debug information may contain internal details or personal data. Add only accounts that need this information for support; removing a login withdraws this additional permission.'=>'Debug-Informationen können interne Details oder personenbezogene Daten enthalten. Tragen Sie nur Konten ein, die diese Informationen für den Support benötigen. Das Entfernen eines Logins entzieht diese Zusatzberechtigung.','Website Functions'=>'Website Funktionen','XML-RPC'=>'XML-RPC','Admin email verification'=>'Admin-E-Mail-Bestätigung','Emoji'=>'Emoji','Google Fonts'=>'Google-Schriften','Discussion'=>'Diskussion','Discussion Defaults'=>'Diskussions-Standards','Disable Avatars'=>'Avatare deaktivieren','Other Functions'=>'Sonstige Funktionen','Delete Website'=>'Website löschen','Privacy Options'=>'Datenschutzoptionen','Disable AI Functionality'=>'KI-Funktionalität deaktivieren','Hide AI Connector Page for Users'=>'KI-Connector-Seite für Benutzer ausblenden','Disable Font Library in Admin Dashboard'=>'Schriftartenbibliothek im Admin-Dashboard deaktivieren','Additional website-related functions that are applied across the multisite network.'=>'Weitere websitebezogene Funktionen, die im gesamten Multisite-Netzwerk angewendet werden.','General website features that are applied across the multisite network.'=>'Allgemeine Website-Funktionen, die im gesamten Multisite-Netzwerk angewendet werden.','Network administrators can centrally configure discussion settings across the multisite network.'=>'Netzwerkadministratoren können Diskussionseinstellungen im gesamten Multisite-Netzwerk zentral konfigurieren.','Disables the delete site feature'=>'Deaktiviert die Funktion zum Löschen der Website','Disables the privacy settings'=>'Deaktiviert die Datenschutzeinstellungen','Disable AI functionality in WordPress.'=>'Deaktiviert KI-Funktionalität in WordPress.','Hide the AI Connectors settings page for users and block direct access.'=>'Blendet die Einstellungsseite für KI-Connectors für Benutzer aus und blockiert den direkten Zugriff.','Hide the Font Library page in the admin dashboard and block direct access.'=>'Blendet die Schriftartenbibliothek im Admin-Dashboard aus und blockiert den direkten Zugriff.','Disables the XML-RPC API'=>'Deaktiviert die XML-RPC-API','Disables the admin email verification check'=>'Deaktiviert die Überprüfung der Administrator-E-Mail-Verifizierung','Disables Emoji graphics'=>'Deaktiviert Emoji-Grafiken','Disables loading of Google Fonts'=>'Deaktiviert das Laden von Google-Schriften','Apply restrictive discussion defaults'=>'Restriktive Diskussions-Standards anwenden','For new websites, comments and pingbacks are disabled by default and commenting requires a login. Across the network, new posts and pages get closed comments by default, and anonymous commenting is blocked.'=>'Bei neuen Websites werden Kommentare und Pingbacks standardmäßig deaktiviert, und Kommentieren erfordert eine Anmeldung. Netzwerkweit werden Kommentare für neue Beiträge und Seiten standardmäßig geschlossen, und anonymes Kommentieren wird blockiert.','Disable avatars settings'=>'Avatareinstellungen deaktivieren','Writing'=>'Schreiben','Post Lock'=>'Post-Sperre','Disable Custom Fields Metabox'=>'Metabox für benutzerdefinierte Felder deaktivieren','Default Editor'=>'Standardeditor','Enable Block Editor for New Sites'=>'Block-Editor für neue Websites aktivieren','Classic Editor'=>'Klassischer Editor','Block Editor'=>'Block-Editor','Post Types Exceptions'=>'Ausnahmen für Post-Types','Themes Exceptions'=>'Ausnahmen für Themes','Websites Exceptions'=>'Ausnahmen für Websites','Autosave Interval'=>'Autosave-Intervall','Interval in seconds for the autosave feature. Minimum is 15 seconds.'=>'Intervall in Sekunden für die Autosave-Funktion. Minimum sind 15 Sekunden.','Sync Autosave Interval With Heartbeat'=>'Autosave-Intervall mit Heartbeat synchronisieren','If enabled, the autosave interval will be synchronized with the Heartbeat API interval.'=>'Wenn aktiviert, wird das Autosave-Intervall mit dem Heartbeat-API-Intervall synchronisiert.','Allowed Blocks'=>'Erlaubte Blöcke','Disabled Blocks'=>'Deaktivierte Blöcke','Disable Block Directory Assets'=>'Blockverzeichnis-Assets deaktivieren','Disable Remote Block Patterns'=>'Remote-Patterns deaktivieren','Disable Openverse Media'=>'Openverse Medien deaktivieren','Disable Font Library UI'=>'Schriftartenbibliothek-UI deaktivieren','Disable Code Editor'=>'Code-Editor deaktivieren','Disable Custom CSS'=>'Individuelles CSS deaktivieren','Disable Custom CSS Themes'=>'Themes für individuelles CSS deaktivieren','Code Editor Websites Exceptions'=>'Website-Ausnahmen für die Verwendung des Code-Editors','Deactivated Plugins'=>'Deaktivierte Plugins','Post Lock Interval'=>'Post-Sperrintervall','Allow switching editors'=>'Erlaube das Wechseln von Editoren','This page enables network administrators to manage writing-related settings across the multisite network. Available options include enabling or configuring post locking, selecting the default editor (block or classic), specifying allowed and disabled blocks, applying exceptions for particular websites, themes, or post types, and enforcing additional editor restrictions—facilitating a standardized and controlled writing environment across all websites.'=>'Diese Seite ermöglicht Netzwerkadministratoren, schreibbezogene Einstellungen im gesamten Multisite‑Netzwerk zu verwalten. Zu den verfügbaren Optionen gehören das Aktivieren oder Anpassen des Beitragssperrens, die Auswahl des Standard‑Editors (Block‑ oder klassischer Editor), das Festlegen erlaubter und deaktivierter Blöcke, das Anwenden von Ausnahmen für bestimmte Websites, Themes oder Beitragstypen sowie das Durchsetzen zusätzlicher Editor‑Einschränkungen – und so eine standardisierte und kontrollierte Schreibumgebung auf allen Websites zu gewährleisten.','Enable the post lock feature'=>'Aktivieren der Post-Sperrfunktion','Disables the custom fields metabox'=>'Deaktiviert die Metabox für benutzerdefinierte Felder','List of post types that always have the block editor enabled and no block restrictions. Enter one post type per line.'=>'Liste der Post-Types, bei denen der Blockeditor immer aktiviert ist und bei denen es keine Blockbeschränkungen gibt. Geben Sie einen Post-Type pro Zeile ein.','List of themes that always have the block editor enabled and no block restrictions. Enter one theme name per line.'=>'Liste der Themes, bei denen der Blockeditor immer aktiviert ist und keine Blockbeschränkungen gelten. Geben Sie pro Zeile einen Theme-Namen ein.','List of websites ids that always have the block editor enabled and no block restrictions. Enter one website id per line.'=>'Liste der Website-IDs, bei denen der Blockeditor immer aktiviert ist und keine Blockbeschränkungen bestehen. Geben Sie eine Website-ID pro Zeile ein.','List of allowed blocks. The * wildcard is supported at the end of a string.'=>'Liste der zulässigen Blöcke. Das Platzhalterzeichen * wird am Ende einer Zeichenfolge unterstützt.','If this field is left empty, all registered blocks will be available.'=>'Wenn dieses Feld leer bleibt, sind alle registrierten Blöcke verfügbar.','Enter one block type per line.'=>'Geben Sie pro Zeile einen Blocktyp ein.','List of disabled blocks. The * wildcard is supported at the end of a string.'=>'Liste der deaktivierten Blöcke. Der Platzhalter * wird am Ende einer Zeichenfolge unterstützt.','Remove Block Directory assets'=>'Blockverzeichnis-Assets entfernen','Disable remote block patterns'=>'Remote-Patterns deaktivieren','Disable loading of Openverse Media'=>'Laden von Openverse Media deaktivieren','Disable the Font Library user interface'=>'Benutzeroberfläche der Font-Bibliothek deaktivieren','Disable the Code Editor option from the Block Editor settings'=>'Die Option Code-Editor in den Block-Editor-Einstellungen deaktivieren','Disable Custom CSS support in Block Editor blocks'=>'Unterstützung für individuelles CSS in Block-Editor-Blöcken deaktivieren','List of themes where Custom CSS support should be disabled in the Block Editor. Enter one theme name or stylesheet per line. Leave empty to apply to all themes.'=>'Liste der Themes, in denen die Unterstützung für individuelles CSS im Block-Editor deaktiviert werden soll. Pro Zeile einen Theme-Namen oder ein Stylesheet eingeben. Leer lassen, um die Einstellung auf alle Themes anzuwenden.','List of websites ids that always have the code editor enabled. Enter one website id per line.'=>'Liste der Website-IDs, bei denen der Code-Editor immer aktiviert ist. Geben Sie pro Zeile eine Website-ID ein.','Plugins to disable when the block editor is active. Enter one plugin per line.'=>'Plugins, die deaktiviert werden sollen, wenn der Blockeditor aktiv ist. Geben Sie pro Zeile ein Plugin ein.','The plugin name must be the same as in the plugins folder.'=>'Der Plugin-Name muss mit dem im Plugin-Ordner übereinstimmen.','Enable Block Editor for new sites'=>'Block-Editor für neue Websites aktivieren','Post Lock interval in seconds.'=>'Post-Sperrinterval in Sekunden.','Allow admins to switch editors'=>'Erlaube Administratoren, Editoren zu wechseln','Classic editor'=>'Klassischer Editor','Block editor'=>'Block-Editor','The plugin "%s" has been deactivated because the block editor is enabled on this website.'=>'Das Plugin „%s“ wurde deaktiviert, da der Blockeditor auf dieser Website aktiviert ist.','Editor'=>'Editor','Block'=>'Block','Classic'=>'Klassisch','Filter by editor'=>'Nach Editor filtern','All editors'=>'Alle Editoren','The server is running WordPress version %1$s. The plugin requires at least WordPress version %2$s.'=>'Auf dem Server wird die WordPress-Version %1$s ausgeführt. Das Plugin erfordert mindestens die WordPress-Version %2$s.','The server is running PHP version %1$s. The plugin requires at least PHP version %2$s.'=>'Auf dem Server wird die PHP-Version %1$s ausgeführt. Das Plugin erfordert mindestens die PHP-Version %2$s.','The plugin can only be installed in a multisite installation and network-wide.'=>'Das Plugin kann nur in einer Multisite-Installation und netzwerkweit installiert werden.','Too many administrators'=>'Maximale Anzahl von Administratoren erreicht','This site already has %d user with the Administrator role.'=>'Diese Website hat bereits %d Benutzer mit der Rolle Administrator.' . "\0" . 'Diese Website hat bereits %d Benutzer mit der Rolle Administrator.','Having too many administrators can cause:
• Risk of accidental configuration changes
• Reduced traceability and accountability
• Larger attack surface if an account is compromised
• Governance and support complexity

If you still wish to proceed, type EXACTLY the confirmation phrase below:'=>'Eine zu hohe Anzahl von Administratoren kann folgende Risiken verursachen:

• Risiko unbeabsichtigter Konfigurationsänderungen
• Geringere Nachvollziehbarkeit und Verantwortlichkeit
• Größere Angriffsfläche bei kompromittierten Benutzerkonten
• Erhöhte Komplexität in Governance und Support

Wenn Sie dennoch fortfahren möchten, geben Sie bitte EXAKT die untenstehende Bestätigungsphrase ein:','Confirmation phrase'=>'Bestätigungstext','You must type the phrase exactly as shown (case-sensitive).'=>'Sie müssen die Phrase exakt wie angezeigt eingeben (Groß- und Kleinschreibung beachten).','The phrase does not match.'=>'Die Bestätigungsphrase stimmt nicht überein.','Proceed anyway'=>'Trotzdem fortfahren','Metatags'=>'Metatags','Google Notranslate'=>'Google Notranslate','Google Translate'=>'Google Translate','Controls which metatag settings website administrators can configure locally.'=>'Steuert, welche Metatag-Einstellungen Website-Administratoren lokal konfigurieren können.','Allow website administrators to tell Googlebot that this website should not be offered by Google as a translated copy.'=>'Erlaube es Website-Administratoren, dem Googlebot mitzuteilen, dass diese Website nicht von Google in einer übersetzten Kopie angeboten werden soll.','Prevent Google from creating a copy of the website in other languages and offering it under its own domain.'=>'Verbiete es Google, eine Kopie der Website in anderen Sprachen anzulegen und unter eigener Domain anzubieten.','Site header'=>'Seitenkopf','Site footer'=>'Seitenfuß','Error'=>'Fehler','Error accessing the website'=>'Fehler beim Aufruf der Website','Contact the webmaster of this website:'=>'Kontakt zum Webmaster des Webauftritts:','Legal notices'=>'Rechtliche Hinweise','Imprint'=>'Impressum','Privacy policy'=>'Datenschutz','Accessibility statement'=>'Barrierefreiheit']];